Project Employees I.schema:
CREATE TABLE Project (
    project_id INT,
    employee_id INT,
    PRIMARY KEY (project_id, employee_id)
);
CREATE TABLE Employee (
    employee_id INT PRIMARY KEY,
    name VARCHAR(30),
    experience_years INT
);

Percentage of Users Attended a Contest.schema:
CREATE TABLE Users (
    user_id INT PRIMARY KEY,
    user_name VARCHAR(20)
);
CREATE TABLE Register (
    contest_id INT,
    user_id INT,
    PRIMARY KEY (contest_id, user_id)
);

Queries Quality and Percentage.schema:
CREATE TABLE Queries (
    query_name VARCHAR(30),
    result VARCHAR(50),
    position INT,
    rating INT
);

Immediate Food Delivery II.schema:
CREATE TABLE Delivery (
    delivery_id INT PRIMARY KEY,
    customer_id INT,
    order_date DATE,
    customer_pref_delivery_date DATE
);

Number of Unique Subjects Taught by Each.schema:
CREATE TABLE Teacher (
    teacher_id INT,
    subject_id INT,
    dept_id INT,
    PRIMARY KEY (teacher_id, subject_id)
);

User Activity for the Past 30 Days I.schema:
CREATE TABLE Activity (
    user_id INT,
    session_id INT,
    activity_date DATE,
    activity_type ENUM('open_session', 'end_session', 'scroll_down', 'send_message')
);

Product Sales Analysis III.schema:
CREATE TABLE Sales (
    sale_id INT,
    product_id INT,
    year INT,
    quantity INT,
    price INT,
    PRIMARY KEY (sale_id, product_id, year)
);
CREATE TABLE Product (
    product_id INT PRIMARY KEY,
    product_name VARCHAR(10)
);

Classes More Than 5 Students.schema:
CREATE TABLE Courses (
    student VARCHAR(255),
    class VARCHAR(255),
    PRIMARY KEY (student, class)
);

Find Followers Count.schema:
CREATE TABLE Followers (
    user_id INT,
    follower_id INT,
    PRIMARY KEY (user_id, follower_id)
);

Customers Who Bought All Products.schema:
CREATE TABLE Customer (
    customer_id INT,
    product_key INT
);
CREATE TABLE Product (
    product_key INT PRIMARY KEY
);

The Number of Employees Which Report to.schema:
CREATE TABLE Employees (
    employee_id INT PRIMARY KEY,
    name VARCHAR(20),
    reports_to INT,
    age INT
);

Primary Department for Each Employee.schema:
CREATE TABLE Employee (
    employee_id INT,
    department_id INT,
    primary_flag ENUM('Y', 'N'),
    PRIMARY KEY (employee_id, department_id)
);
